def preencher_estado(apps, schema_editor):
    """Contas antigas tinham só a cidade: deduz o estado quando a cidade é conhecida."""
    Perfil = apps.get_model("ArtConnect", "Perfil")
    for perfil in Perfil.objects.filter(estado=""):
        cidade = perfil.cidade.strip().lower()
        for nome, sigla in CIDADES_CONHECIDAS:
            if cidade == nome:
                perfil.estado = sigla
                perfil.save(update_fields=["estado"])
                break


